import Mathlib

def GeometricPolynomial (Q : Polynomial ℤ) : Prop :=
  Q.degree ≥ 2 ∧ ∃ (a r : ℤ), r ≠ 0 ∧ Set.Infinite {k : ℤ | ∃ (n : ℕ), Q.eval k = a * r^n}

theorem geometric_polynomial_eval (Q : Polynomial ℤ) (hQ : GeometricPolynomial Q)
  (h_lead : Q.leadingCoeff = 64) (h_const : Q.coeff 0 = -486) : Q.eval 5 = 162 := by sorry
